(()=>{const b=window.DriveQuizBank;if(!b)throw Error("Missing DriveQuizBank");b.questions.push(...[{"id":"rodrive-b-0551","batch":"12","category":"Categoria B","question":"Balansarea, în plan vertical, a brațului drept al unui biciclist semnifică:","answers":["Intenția de a schimba direcția de mers la dreapta","Intenția de a opri","Intenția de a se angaja în depășire"],"correctIndices":[1],"correct":1,"explanation":"Semnalul efectuat de conducătorul de bicicletă prin balansarea în plan vertical a brațului drept semnifică intenția acestuia de a opri.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0551.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0551.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 551; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 550 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/balansarea-in-plan-vertical-a-bratului-drept-al-unui-biciclist-semnifica","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"550","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0552","batch":"12","category":"Categoria B","question":"Conducătorul unui autovehicul poate executa o depășire la întâlnirea indicatorului „Limitare de viteză“?","answers":["Da, dacă în timpul manevrei viteza sa nu este mai mare decât cea înscrisă pe indicator","Nu, până la întâlnirea indicatorului care semnalizează terminarea zonei de limitare a vitezei","Da, dacă depășirea se execută în afara unei localități"],"correctIndices":[0],"correct":0,"explanation":"Atunci când întâlniți indicatorul “Limitare de viteză”, ca de exemplu indicatorul „Limitare de vitează la 70 de km/h”, puteți executa manevra de depasire, însa în timpul manevrei nu trebuie să aveți o viteză mai mare de 70 de km/h. Trebuie știut că indicatorul “Limitare de viteză” nu interzice manevra de depășire, acesta stabilește doar limita maximă de viteză pe care administratorul drumului a stabilit-o pe acel sector de drum.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0552.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0552.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 552; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 551 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/conducatorul-unui-autovehicul-poate-executa-o-depasire-la-intalnirea-indicatorului-limitare-de-viteza","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"551","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0553","batch":"12","category":"Categoria B","question":"Cum trebuie să procedeze conducătorul de vehicul atunci când, într-o intersecție, întâlnește un polițist orientat cu fața spre el, care îi face semn să-și continue deplasarea?","answers":["Oprește până când polițistul își schimbă poziția","Fiind un semnal în afara regulamentului, oprește și așteaptă revenirea la o poziție care să-i permită continuarea drumului","Se conformează semnalului polițistului"],"correctIndices":[2],"correct":2,"explanation":"Atunci când intersecția este dirijată cu polițist de circulație, aveți obligația de a respecta semnalele adresate de acesta. Deci atunci când polițistul rutier vă adresează un semnal de continuare a deplasării, aveți obligația de a vă conforma cu semnalul polițistului și trebuie să vă continuați deplasarea.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0553.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0553.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 553; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 552 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/cum-trebuie-sa-procedeze-conducatorul-de-vehicul-atunci-cand-intr-o-intersectie-intalneste-un-politist-orientat-cu-fata-spre-el-care-ii-face","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"552","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0554","batch":"12","category":"Categoria B","question":"Autobuzul este staționat. Care dintre cei doi conducători procedează neregulamentar?","answers":["Conducătorul autobuzului","Conducătorul autoturismului","Ambii conducători procedează regulamentar"],"correctIndices":[0],"correct":0,"explanation":"În situația dată autobuzul este staționat neregulamentar, deoarece staționarea este interzisă în dreptul marcajului continuu atunci când conducătorii celorlalte vehicule care circulă în același sens sunt obligați din această cauză să treacă peste acest marcaj. Deci în situația dată autobuzul este staționat neregulamentar, deoarece obligă autoturismul la efectuarea manevrei de depășire trecând peste marcajul continuu.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0554.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0554.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 554; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă un autobuz staționat pe partea dreaptă a drumului, iar vehiculul albastru semnalizează intenția de a depăși. Autoturismul ar trebui să calce pe marcajul longitudinal pentru a depăși autobuzul, dar pentru a putea circula ar fi obligat să îl depășească.","needsImageReview":true,"source":"RoDrive · ID 553 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/autobuzul-este-stationat-care-dintre-cei-doi-conducatori-procedeaza-neregulamentar","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"553","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_567.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0555","batch":"12","category":"Categoria B","question":"Cum veți proceda la semnalul polițistului, atunci când conduceți autoturismul din imagine?","answers":["Opriți, deoarece semnalul vi se adresează","Vă continuați deplasarea, deoarece semnalul nu vi se adresează","Schimbați direcția de mers spre stânga"],"correctIndices":[1],"correct":1,"explanation":"Polițistul din intersecție execută un semnal cu brațul drept întins orizontal, acest semnal semnifică oprire pentru toți participanții la trafic a căror direcție inițială de deplasare se intersectează cu brațul acestuia, mai exact pentru cei care vin din spatele polițistului. Prin urmare, conducând autoturismul albastru vă puteți continua deplasarea, semnalul de oprire nu vi se adresează deoarece direcția dumneavoastră inițială de deplasare nu se intersectează cu brațul acestuia.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0555.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0555.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 555; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă o intersecție dirijată de un polițist rutier. Polițistul cu brațul drept întins lateral indică oprirea pentru vehiculele care vin din spate. Vehiculul albastru din imagine se află în fața polițistului.","needsImageReview":true,"source":"RoDrive · ID 554 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/cum-veti-proceda-la-semnalul-politistului-atunci-cand-conduceti-autoturismul-din-imagine","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"554","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_568.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0556","batch":"12","category":"Categoria B","question":"Cum veți proceda în intersecția care urmează?","answers":["Acordați prioritate numai vehiculelor care vin din stânga","Acordați prioritate numai vehiculelor care vin din dreapta","Acordați prioritate celor în drept"],"correctIndices":[2],"correct":2,"explanation":"În situația dată întâlniți indicatorul „Cedează trecerea” însoțit de panoul adițional „50 metri”. Acestea vă avertizează că peste 50 de metri intrați într-o intersecție unde veți întâlni indicatorul „Cedează trecerea” fiind obligați să reduceți viteza și să acordați prioritate celor ce au acest drept, adică celor care circulă pe drumul transversal, indiferent de direcția acestora de deplasare.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0556.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0556.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 556; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă un drum urban cu indicatorul triunghiular cu margini roșii, 'Cedează trecerea' amplasat la 50 de metri înainte de intersecție, fapt indicat de panoul adițional de sub el pe care scrie 50.","needsImageReview":true,"source":"RoDrive · ID 555 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/cum-veti-proceda-in-intersectia-care-urmeaza","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"555","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_569.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0557","batch":"12","category":"Categoria B","question":"Care este rolul marcajelor rezonatoare?","answers":["Dublează marcajele convenționale în zonele periculoase","Avertizează conducătorii de autovehicule că depășesc zona de carosabil marcată și destinată sensului de deplasare","Avertizează conducătorii de autovehicule că vor pătrunde într-o zonă supravegheată cu aparatură radar"],"correctIndices":[1],"correct":1,"explanation":"Marcajele rezonatoare sunt acele marcaje care în interacțiune cu anvelopele mașinii creează o vibrație având un puternic efect rezonator. Rolul acestora este să avertizeze conducătorii de autovehicule că depășesc zona de carosabil marcată și destinată sensului de deplasare. Marcajele rezonatoare se găsesc, de regulă, pe autostrăzi, pe drumurile expres și pe drumuri naționale europene, la extremitățile părții carosabile.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0557.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0557.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 557; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 556 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/care-este-rolul-marcajelor-rezonatoare","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"556","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0558","batch":"12","category":"Categoria B","question":"Întoarcerea este interzisă:","answers":["Pe străzile cu sens unic","În intersecții și la mai puțin de 50 m de cel mai apropiat colț al intersecției","La mai puțin de 100 m de o trecere la nivel cu calea ferată"],"correctIndices":[0],"correct":0,"explanation":"Legislația rutierăinterziceîntoarcerea vehiculului pe drumurile pe care circulația se desfășoară în sens unic. Dacă ați întoarce vehiculul, având în vedere că circulația se desfășoară în sens unic, ați circula în sens opus vehiculelor care se deplasează regulamentar, mai exact ați circula pe sensul opus. Întoarcerea vehiculelorNUeste interzisă în intersecții, nici în cele cu circulație în sens giratoriu, sau la mai puțin de 50 de metri de cel mai apropiat colț al unei intersecției. Însă întoarcerea vehiculului este interzisă în intersecțiileîn care se interzice virajul către stângasau în intersecțiile în careeste necesară manevrarea vehiculului înainte și înapoi. Întoarcerea vehiculelorNUeste interzisă la mai puțin de100 de metride trecerile la nivel cu calea ferată, dar este interzis pe trecerile la nivel cu calea ferată curentă și la o distanțămai mica de 50 metriînainte și după acestea. Dacă ați selecta varianta C de răspuns ați fi de acord că întoarcerea vehiculelor este interzisă la o distanță cuprinsă între 50 și 100 de metri (de la 50 la 100 de metri) de trecerea la nivel cu calea ferată curentă, ceea ce este greșit.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0558.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0558.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 558; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 557 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/intoarcerea-este-interzisa","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"557","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0559","batch":"12","category":"Categoria B","question":"Ce trebuie să aveți în vedere atunci când lăsați copiii să urce sau să coboare din autoturismul pe care îl conduceți?","answers":["Copiii trebuie invitați să urce sau să coboare numai pe partea dinspre trotuar","Copiilor le este permis să coboare singuri, pe orice parte","Nu trebuie să aveți nimic în vedere, deoarece copiii se comportă întotdeauna corect în circulație"],"correctIndices":[0],"correct":0,"explanation":"Conducătorului de autovehicul îi este interzis ca în timpul opririi sau staționării să deschidă ori să lase deschise ușile acestuia fără să se asigure. Dar în cazul în care transportă copii trebuie să se asigure că minorii știu să urce sau să coboare numai pe partea dinspre trotuar și că nu au voie să deschidă ușile dinspre partea carosabilă fără permisiunea conducătorului, care s-a asigurat în prealabil.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0559.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0559.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 559; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 558 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/ce-trebuie-sa-aveti-in-vedere-atunci-cand-lasati-copiii-sa-urce-sau-sa-coboare-din-autoturismul-pe-care-il-conduceti","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"558","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0560","batch":"12","category":"Categoria B","question":"Ce trebuie să aveți în vedere înaintea transportării unei victime la spital?","answers":["Ca funcția respiratorie și funcția circulatorie să fie asigurate","Ca punctul sanitar către care vă îndreptați să nu fie la o distanță mai mare de 50 km","Ca autovehiculul cu care va fi transportată victima să asigure confortul necesar"],"correctIndices":[0],"correct":0,"explanation":"Transportarea victimelor la spital se poate realiza cu o ambulanță special dotată în acest sens, de regulă, însoțită de un medic. Dar dacă,în lipsa altor mijloace de transport și dacă starea victimei permite, conducătorul vehiculului transportă el însuși, cu vehiculul care a provocat accidentul, persoanele rănite la cel mai apropiat spital și declară datele personale și numărul vehiculului condus, acestea fiind consemnate într-un registru special, și dacă se înapoiază imediat la locul accidentului,NU CONSTITUIE INFRACȚIUNE. Înaintea transportării unei victime la spital, trebuie să aveți în vedere ca funcția respiratorie și funcția circulatorie ale acestuia să fie asigurate.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0560.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0560.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 560; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 559 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/ce-trebuie-sa-aveti-in-vedere-inaintea-transportarii-unei-victime-la-spital","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"559","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0561","batch":"12","category":"Categoria B","question":"Ce obligații aveți, în calitate de conducător auto?","answers":["Să circulați cu o viteză cel puțin egală celei prescrise de indicatorul „viteză minimă obligatorie“","Să nu accelerați în intersecție","Să circulați cu o viteză inferioară celei înscrise în indicatorul „viteză minimă obligatorie“"],"correctIndices":[0],"correct":0,"explanation":"În calitate de conducător auto aveți obligația de a respecta semnificația indicatoarelor, ca de exemplu semnificația indicatorului „Viteză minimă obligatorie”. La întâlnirea acestui indicator aveți obligația de a circula cu o viteză cel puțin egală cu cea înscrisa pe indicator, adică veți circula cu cel puțin 60 de km/h. În intersecții nu este interzis să se accelereze. De cele mai multe ori este necesar să se accelereze, ca de exemplu atunci când pătrundeți în intersecție după ce ați oprit pentru a vă asigura la indicatorul „Oprire”.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0561.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0561.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 561; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 560 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/ce-obligatii-aveti-in-calitate-de-conducator-auto","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"560","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0562","batch":"12","category":"Categoria B","question":"Indicatorul semnifică:","answers":["Claxonatul este permis numai în cazul evitării unui pericol imediat","Folosirea claxonului este permisă numai pe timp de zi","Folosirea claxonului este permisă numai în condiții de vizibilitate redusă"],"correctIndices":[0],"correct":0,"explanation":"Indicatorul se numește “Claxonarea interzisă”, acest indicator interzice claxonarea, dar pentru că acesta este instalat lângă indicatorul de localitate, claxonarea este interzisă pe întreg teritoriul localității. Chiar dacă se interzice claxonarea, aceasta este permisă conducătorilor de autovehicule care folosesc acest semnal pentru evitarea unui pericol imediat.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0562.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0562.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 562; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Indicatorul circular cu margini roșii, care prezintă un claxon peste care este trasată o linie roșii este amplasat la intrarea în localitatea Făgăraș. Acest indicator interzice claxonatul, mai puțin în situații de urgență.","needsImageReview":true,"source":"RoDrive · ID 561 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/indicatorul-semnifica","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"561","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_576.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0563","batch":"12","category":"Categoria B","question":"Ce autovehicule pot opri în rândul doi, lângă alte vehicule staționate pe partea dreaptă a carosabilului?","answers":["Toți cei care au ceva urgent de rezolvat","Taximetrele, la urcarea sau coborârea pasagerilor, atunci când circulația permite acest lucru","Orice autoturism"],"correctIndices":[1],"correct":1,"explanation":"Oprirea este interzisăîn dreptul altui vehicul oprit pe partea carosabilă, dacă prin aceasta se stânjenește circulația a două vehicule venind din sensuri opuse, precum și în dreptul marcajului continuu, în cazul în care conducătorii celorlalte vehicule care circulă în acelasi sens ar fi obligați, din această cauză, să treacă peste acest marcaj. Nu este considerată oprire, imobilizarea unui vehicul pentru îmbarcarea sau debarcarea unor persoane, dacă această manevră nu perturbă circulația pe drumul public. Deci, taximetrele (dar și alte vehicule) pot opri, la urcarea sau coborârea pasagerilor,dacă nu încurcă circulația pe drumul public.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0563.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0563.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 563; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 562 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/ce-autovehicule-pot-opri-in-randul-doi-langa-alte-vehicule-stationate-pe-partea-dreapta-a-carosabilului","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"562","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0564","batch":"12","category":"Categoria B","question":"Cum procedează conducătorul de vehicul care intenționează să circule pe direcția înainte printr-o intersecție nedirijată?","answers":["Reduce viteza și acordă prioritate tuturor vehiculelor","Reduce viteza și acordă prioritate vehiculelor care vin din dreapta sa","Reduce viteza și acordă prioritate vehiculelor care circulă din sens opus și urmează să schimbe direcția de mers spre stânga"],"correctIndices":[1],"correct":1,"explanation":"Având în vedere că în intersecțiile nedirijate se aplică „prioritatea de dreapta”, nu trebuie să acordați prioritate tuturor vehiculelor, ci doar celor care vă vin din partea dreaptă. Vehiculele care vin din partea stângă trebuie să vă acorde dvs. „prioritate de dreapta”. Atunci când intenționați să circulați printr-o intersecție nedirijată, aveți obligația de a circula cu 30 km/h în localități sau 50 km/h în afara localităților și de a ceda trecerea vehiculelor care vă vin din partea dreaptă. Acest tip de prioritate se mai numește și „prioritate de dreapta”. Având în vedere că dvs. intenționați să circulați pe direcția înainte, vehiculele care circulă din sens opus și urmează să schimbe direcția de mers spre stânga trebuie să vă acorde dvs. prioritate pentru că, în timpul virajului spre stânga pe care îl efectuează acestea, dvs. le veniți din partea dreaptă.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0564.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0564.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 564; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 563 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/cum-procedeaza-conducatorul-de-vehicul-care-intentioneaza-sa-circule-pe-directia-inainte-printr-o-intersectie-nedirijata","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"563","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0565","batch":"12","category":"Categoria B","question":"Care este limita maximă de viteză pe autostrăzi?","answers":["110 km/h","100 km/h","130 km/h"],"correctIndices":[2],"correct":2,"explanation":"Limita maximă de viteză pe drumurile din afara localităților este de130 km/h pe autostrăzi, 120 km/h pe drumurile expres, 100 km/h pe drumurile naționale europene (E) și 90 km/h pe celelalte categorii de drumuri. Aceste limite maxime de viteză sunt limitele maxime care se pot stabilii pe drumurile publice din România. Trebuie știut că,în funcție de categoria drumului pe care se circulă și de categoria autovehiculului condus, limitele maxime de viteză sunt diferite. Limitele maxime de viteză pentru autovehiculele din categoriile A și B pe drumurile din afara localităților coincid cu limitele maxime care se pot stabilii pe drumurile publice din România:130 km/h pe autostrăzi, 120 km/h pe drumurile expres, 100 km/h pe drumurile naționale europene (E) și 90 km/h pe celelalte categorii de drumuri.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0565.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0565.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 565; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 564 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/care-este-limita-maxima-de-viteza-pe-autostrazi","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"564","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0566","batch":"12","category":"Categoria B","question":"Ce indică semnalul polițistului?","answers":["Oprire","Măriți viteza","Reduceți viteza"],"correctIndices":[2],"correct":2,"explanation":"Semnalul adresat de către polițistul rutier, prin balansarea pe verticală a brațului, având palma orientată catre sol, semnifică reducerea vitezei de deplasare.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0566.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0566.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 566; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă un polițist rutier. Mișcarea brațului în sus și în jos indică reducerea vitezei pentru vehiculele care vin din direcția indicată.","needsImageReview":true,"source":"RoDrive · ID 565 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/ce-indica-semnalul-politistului","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"565","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_580.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0567","batch":"12","category":"Categoria B","question":"Ce obligații aveți la trecerea la nivel cu calea ferată curentă prevăzută cu bariere, dacă acestea sunt ridicate?","answers":["Vă asigurați că nu sunteți depășit de alt vehicul și vă angajați în traversarea căii ferate","Ziua dați semnale sonore, iar noaptea aprindeți faza de drum intermitentă, apoi traversați","Reduceți viteza, vă asigurați că din partea stângă sau din partea dreaptă nu se apropie un vehicul feroviar, apoi vă angajați în traversare"],"correctIndices":[2],"correct":2,"explanation":"La trecerile la nivel cu calea ferată curentă prevăzută cu bariere aveți obligația de a circula cu viteză redusă și de a vă asigura că din partea stângă sau din partea dreaptă nu se apropie un vehicul feroviar, apoi vă puteți angaja în traversare.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0567.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0567.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 567; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 566 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/ce-obligatii-aveti-la-trecerea-la-nivel-cu-calea-ferata-curenta-prevazuta-cu-bariere-daca-acestea-sunt-ridicate","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"566","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0568","batch":"12","category":"Categoria B","question":"Cum este recomandat să procedați pentru a depăși, în condiții de siguranță, un tramvai oprit într-o stație cu refugiu?","answers":["Să avertizați sonor persoanele aflate în zona stației","Să semnalizați din timp intenția de depășire a tramvaiului","Să reduceți viteza de deplasare"],"correctIndices":[2],"correct":2,"explanation":"Se interzice folosirea abuzivă a claxonului sau de la o distanță mai mică de 25 de metri față de cei cărora li se adresează, dar trebuie știut că acesta se poate folosi în cazul unui pericol imediat, chiar și atunci când este interzis. Prin urmare, veți avertiza sonor pietonii aflați în zona stației, doar dacă există un pericol imediat. Întrebarea se referă la orecomandare, dar semnalizarea intenției de a depăși esteobligatorie, nu este o recomandare, de aceea nu este considerat răspuns corect. Din punct de vedere al conduitei preventive, pentru a depăși în condiții de siguranță un tramvai opritîntr-o stațiecu refugiu, este recomandat să reduceți viteza de deplasare și să respectați toate regulile privind manevra de depășire. Atenție!Vă este interzisă manevra de depășire atunci când întâlniți un tramvai opritîntr-o stațiefără refugiu pentru pietoni, având obligația de a opri în spatele tramvaiului și vă puteți relua deplasarea numai după ce ușile tramvaiului s-au închis și v-ați asigurat că nu puneți în pericol siguranța pietonilor angajați în traversarea drumului public.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0568.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0568.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 568; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 567 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/cum-este-recomandat-sa-procedati-pentru-a-depasi-in-conditii-de-siguranta-un-tramvai-oprit-intr-o-statie-cu-refugiu","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"567","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0569","batch":"12","category":"Categoria B","question":"Care este ordinea de trecere a autovehiculelor prin intersecție?","answers":["Motocicleta, bicicleta, autoturismul","Autoturismul, motocicleta, bicicleta","Bicicleta, autoturismul, motocicleta"],"correctIndices":[1],"correct":1,"explanation":"Intersecția este dirijată prin indicatoare de reglementare de prioritate, sub fiecare indicator se găsește instalat câte un panou adițional care indică direcția drumului cu prioritate. Bicicleta vine de pe drumul fără prioritate, întâlnind indicatorul „Cedează trecerea” și are obligația de a acorda prioritate celorlalte vehicule. Autoturismul și motocicleta vin de pe drumul cu prioritate, ambele întâlnind indicatorul „Drum cu prioritate”, între ele s-a creat o situație de egalitate, situație în care se va aplica regula priorității de dreapta. Motocicleta părăsind drumul cu prioritate va trebuie să îi acorde autoturismului prioritate de dreapta, deoarece autoturismul îi vine din partea dreaptă. Ordinea de trecere este următoarea: autoturismul, urmat de motocicleta iar ultima prin intersecție va trece bicicleta.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0569.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0569.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 569; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă o intersecție nesemaforizată unde vehiculele trebuie să respecte regulile de prioritate. Motocicleta vine din stânga și circulă înainte .Autoturismul roșu virează la stânga și vine de jos, acesta fiind pe drum prioritar, marcat de indicatorul romboid cu fundal galben si margini albe și panoul adițional care îngroașă drumul de jos, către stânga. Biciclistul, care vine din partea dreaptă, intenționează să vireze la stânga","needsImageReview":true,"source":"RoDrive · ID 568 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/care-este-ordinea-de-trecere-a-autovehiculelor-prin-intersectie","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"568","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_583.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0570","batch":"12","category":"Categoria B","question":"Ce semnificație are marcajul longitudinal continuu de separare a sensurilor de circulație?","answers":["Orientează conducătorii de vehicule în condiții de vizibilitate redusă","Interzice încălcarea lui","Interzice depășirea pe sectorul pe care este aplicat"],"correctIndices":[1],"correct":1,"explanation":"Legislația rutieră nu prevede nimic în acest sens. Marcajul longitudinal format dintr-o linie continuă simplă sau dublă interzice încălcarea acestuia, indiferent de situație. Marcajul longitudinal continuu de separare a sensurilor de circulațieNU interzicedepășirea pe sectorul pe care este aplicat. Depășirea este permisă pe acel sector, atât timpcât nu se încalcăsau nu se trece peste marcajul longitudinal continuu. Dacă pentru depășirenu s-ar încălcamarcajul longitudinal continuu, depășirea ar fi regulamentară.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0570.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0570.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 570; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 569 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/ce-semnificatie-are-marcajul-longitudinal-continuu-de-separare-a-sensurilor-de-circulatie","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"569","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0571","batch":"12","category":"Categoria B","question":"Oprirea este interzisă:","answers":["Pe sectoarele de drum unde depășirea este interzisă","În zona de acțiune a indicatorului „staționarea interzisă“","În dreptul căilor de acces care deservesc proprietățile alăturate drumurilor publice"],"correctIndices":[0],"correct":0,"explanation":"Oprirea voluntară a vehiculelor este interzisă și în locurile în care manevra de depășire este interzisă. De exemplu, la întâlnirea indicatorului „Depășirea autovehiculelor, cu excepția motocicletelor fără ataș, interzisă”, fiind interzisă manevra de depășire, se interzice și manevra de oprire. În aceste locuri în care se interzice manevra de depășire, este binevenită interzicerea de a opri, având în vedere că dacă oprim o să îl obligam pe cel care circulă în spatele nostru să depășească, deși el nu are voie să efectueze această manevră în acel loc. În zona de acțiune a indicatorului „Staționarea interzisă” se interzice staționarea, nu se interzice și oprirea. Trebuie știut că diferența dintre oprire și staționare constă în perioada de timp pe care este imobilizat vehiculul. O imobilizare a vehiculului de până la 5 minute se numește oprire, iar dacă durează mai mult de 5 minute, se numește staționare. Prin urmare, daca imobilizarea vehiculului este de pana la 5 minute, se numește oprire și este permisă în locurile în care este interzisă staționarea. În dreptul căilor de acces care deservesc proprietățile alăturate drumului public se interzice doar staționarea, oprirea fiind permisă. Trebuie știut că diferența dintre oprire și staționare constă în perioada de timp pe care este imobilizat vehiculul. O imobilizare a vehiculului de până la 5 minute se numește oprire, iar dacă durează mai mult de 5 minute, se numește staționare. Prin urmare, daca imobilizarea vehiculului este de pana la 5 minute, se numește oprire și este permisă în locurile în care este interzisă staționarea.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0571.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0571.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 571; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 570 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/oprirea-este-interzisa","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"570","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0572","batch":"12","category":"Categoria B","question":"Ce se recomandă pe timp de noapte, din punct de vedere al conduitei preventive, pentru un conducător de autovehicul începător?","answers":["Să aibă bateria de acumulatori în stare bună de funcționare","Să evite, pe cât posibil, deplasarea, dacă trebuie să parcurgă un traseu lung, care cuprinde drumuri intens circulate","Să aibă în dotare setul de triunghiuri reflectorizante, precum și becuri de rezervă, pentru a asigura funcționarea ireproșabilă a farurilor"],"correctIndices":[1],"correct":1,"explanation":"Această recomandare este valabilă pentru toți participanții la trafic, nu doar pentru cei începători. În plus, această recomandare face parte din cunoștințele de mecanică auto, nu din cele de conduită preventivă. Conducerea pe timp de noapte este mult mai solicitantă decât conducerea pe timp de zi, iar la parcurgerea traseelor lungi intervine oboseala. Astfel de trasee lungi pe timp de noapte, împreună cu circulația intensă, pot crea probleme chiar și șoferilor experimentați. Prin urmare, din punct de vedere al conduitei preventive,se recomandăconducătorilor de autovehicule începători care circulă pe timp de noapte, să evite,pe cât posibil, deplasarea, dacă trebuie să parcurgă un traseu lung, care cuprinde drumuri intens circulate. Recomandările de la această variantă de răspuns sunt valabile pentru toți participanții la trafic, nu doar pentru cei începători. În plus, setul de triunghiuri reflectorizante (două triunghiuri reflectorizante) este o obligație, nu o recomandare.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0572.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0572.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 572; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 571 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/ce-se-recomanda-pe-timp-de-noapte-din-punct-de-vedere-al-conduitei-preventive-pentru-un-conducator-de-autovehicul-incepator","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"571","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0573","batch":"12","category":"Categoria B","question":"Intenționați să vă puneți în mișcare dintr-o parcare de pe marginea șoselei. În spatele dvs. parchează un autoturism. Ce pericol prezintă această situaţie?","answers":["Niciun pericol","Vehiculele care circulă din sens opus vă pot observa cu întârziere","Din cauza vizibilității reduse din spate, vehiculele care vin din urmă pot observa cu întârziere semnalizarea vehiculului dvs"],"correctIndices":[2],"correct":2,"explanation":"Pericolul este descris la varianta C. Dacă autoturismul care parchează se aflăîn spatele dumneavoastră, nu are cum să le obtureze vizibilitatea, spre dumneavoastră, celor care vin din sens opus, atât timp cât acesta este în spatele dumneavoastră. Intenționați să vă puneți în mișcare dintr-o parcare de pe marginea șoselei, iar în spatele dumneavoastră parchează un autoturism. În astfel de situații trebuie să aveți în vedere că, din cauza vizibilității reduse în spate, vehiculele care vin din urmă pot observa cu întârziere semnalizarea vehiculului dumneavoastră. De aceea, se recomandă să așteptați ca autoturismul din spate să finalizeze parcarea, după care să vă asigurați, semnalizați și, dacă este posibil, vă puneți în mișcare.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0573.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0573.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 573; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 572 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/intentionati-sa-va-puneti-in-miscare-dintr-o-parcare-de-pe-marginea-soselei-in-spatele-dvs-parcheaza-un-autoturism-ce-pericol-prezinta-aceas","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"572","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0574","batch":"12","category":"Categoria B","question":"Ce măsuri vor fi luate în cazul conducerii pe drumurile publice a unui vehicul cu defecțiuni grave la mecanismul de direcție?","answers":["Amendă contravențională, reținerea certificatului de înmatriculare, precum și reținerea permisului de conducere în vederea suspendării exercitării dreptului de a conduce autovehicule","Amendă contravențională","Amendă contravențională și reținerea certificatului de înmatriculare"],"correctIndices":[0],"correct":0,"explanation":"În cazul conducerii pe drumurile publice a unui vehicul cu defecțiuni la mecanismul de direcție,se reține certificatul de înmatriculare, și se aplică și următoarele sancțiuni: Într-adevăr, pentru această faptă se aplică amendă contravențională, însă pe lângă aceasta se aplică și sancțiunile și măsurile enumerate la varianta A de răspuns. Prin urmare, varianta B de răspuns nu poate fi corectă. Într-adevăr, pentru această faptă se aplică amendă contravențională și reținerea certificatului de înmatriculare, însă pe lângă aceasta se aplică și sancțiunile și măsurile enumerate la varianta A de răspuns. Prin urmare, varianta C de răspuns nu poate fi corectă.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0574.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0574.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 574; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 573 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/ce-masuri-vor-fi-luate-in-cazul-conducerii-pe-drumurile-publice-a-unui-vehicul-cu-defectiuni-grave-la-mecanismul-de-directie","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"573","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0575","batch":"12","category":"Categoria B","question":"Semaforul instalat pe trotuar are în funcțiune semnalul roșu, iar cel suspendat, pentru direcția de mers la stânga, semnalul verde. Conducătorul de vehicul care dorește să meargă înainte are dreptul să intre în intersecție?","answers":["Da, deoarece semaforul suspendat are semnalul verde în funcțiune","Nu, deoarece semaforul de pe trotuar, care i se adresează, are semnalul roșu în funcțiune","Nu, deoarece deplasarea pe direcția înainte este permisă numai atunci când semnalul verde este în funcțiune la ambele semafoare"],"correctIndices":[1],"correct":1,"explanation":"Atunci când semaforul instalat pe trotuar are în funcțiune semnalul roșu iar cel suspendat, pentru direcția de mers la stânga, semnalul verde. Conducătorii de vehicule care doresc să circule pe direcția înainte sau să vireze către dreapta trebuie să respecte semnificația semaforului instalat pe trotuar, iar cei care doresc să schimbe direcția de mers către stânga trebuie să respecte semnificația semaforului pentru virajul către stânga, adică semaforul suspendat care va avea atașat un panou pe care se regăsește o sageată cu vârful spre stânga. Prin urmare, conducătorul de vehicul care dorește să circule pe direcția înainte nu poate intra în intersecție, deoarece semnalul roșu al semaforului instalat pe troruar nu îi permite trecerea.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0575.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0575.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 575; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 574 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/semaforul-instalat-pe-trotuar-are-in-functiune-semnalul-rosu-iar-cel-suspendat-pentru-directia-de-mers-la-stanga-semnalul-verde-conducatorul","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"574","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0576","batch":"12","category":"Categoria B","question":"Cum procedați în această situație?","answers":["Se recomandă să măriți atenția","Opriți","Accelerați, pentru a nu fi surprins de căderea pietrelor"],"correctIndices":[0],"correct":0,"explanation":"Indicatorul se numește \"Căderi de pietre\", se întâlnește de obicei în zonele montane și avertizează că există pericolul să cadă pietre de pe versanți. Conducătorul de vehiculnueste obligat să reducă viteza dar se recomandă să se circule cu atenţie mărită și să se părăsească cât mai repede posibil zona de acţiune a indicatorului. Dacă lungimea sectorului periculos depășește 300 de metri, acesta va fi însoțit de un panou adițional pe care este inscripționată lungimea sectorului de drum periculos. Toate manevrelesunt permise, dar preventiv, nu sunt recomandate.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0576.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0576.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 576; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă un drum montan cu indicatorul triunghiular cu margini roșii ce are pietre care cad în interiorul său, semnificând 'Căderi de pietre'.","needsImageReview":true,"source":"RoDrive · ID 575 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/cum-procedati-in-aceasta-situatie","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"575","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_590.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0577","batch":"12","category":"Categoria B","question":"În cazul plăgilor însoțite de hemoragii arteriale, persoanelor rănite trebuie să li se aplice un garou de cauciuc:","answers":["Deasupra plăgii","Sub plagă","Peste plagă"],"correctIndices":[0],"correct":0,"explanation":"Garoul este un cordon elastic, care este folosit pentru oprirea sângerării în cazul unor hemoragii care nu pot fi oprite altfel, de obicei în cazul plăgilor membrelor. Acesta se aplică deasupra rănii, pentru a micșora presiunea arterială în zona plăgii. Acesta nu se aplică direct pe piele ci peste o bucată de fașă sau alt material moale și se atașează neapărat un bilet pe care se notează numele victimei si ora exactă a aplicării garoului. În absența unui garou, se poate folosi: un fular, cordon, curea, cravată, șnur, elastic etc. Deși în trecut se recomanda slăbirea garoului la fiecare 15 minute pentru a permite alimentarea cu sânge a membrului, practică nu mai este recomandată în prezent, deoarece poate agrava starea victimei. Consultați personalul specializat prin apel 112 înainte de a efectua această manevră.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0577.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0577.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 577; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 576 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/in-cazul-plagilor-insotite-de-hemoragii-arteriale-persoanelor-ranite-trebuie-sa-li-se-aplice-un-garou-de-cauciuc","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"576","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0578","batch":"12","category":"Categoria B","question":"Semnalul polițistului din autovehiculul de poliție semnifică:","answers":["Oprire","Măriți viteza","Reduceți viteza"],"correctIndices":[0],"correct":0,"explanation":"Semnalul polițistului aflat în autovehiculul poliției prin scoaterea brațului, cu sau fără baston reflectorizant, pe partea laterală dreaptă a autovehiculului, semnifică oprire pentru conducătorii vehiculelor care circulă în spatele autovehiculului poliției.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0578.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0578.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 578; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă un vehicul al poliției care semnalizează oprirea prin intermediul bastonului reflectorizant, pe partea dreaptă.","needsImageReview":true,"source":"RoDrive · ID 577 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/semnalul-politistului-din-autovehiculul-de-politie-semnifica","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"577","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_592.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0579","batch":"12","category":"Categoria B","question":"Ce măsuri ia conducătorul de vehicul, angajat într-un accident cu avarii ușoare?","answers":["Așteaptă sosirea polițistului din zonă","Scoate vehiculul în afara părții carosabile și se prezintă la poliție în termen de 24 de ore","Anunță poliția, fără a schimba poziția vehiculului"],"correctIndices":[1],"correct":1,"explanation":"Conducătorul de vehicul implicat într-un accident de circulațieîn urma căruia au rezultat numai avarierea vehiculelor și/sau alte pagube materiale(fără victime), este obligat să scoată imediat vehiculul în afara parții carosabile ori, dacă starea vehiculului nu permite acest lucru, să îl deplaseze cât mai aproape de bordură sau acostament, semnalizându-i prezența și să se prezinte la unitatea de poliție competentă pe raza căreia s-a produs accidentul în termen de cel mult 24 de ore de la producerea evenimentului pentru întocmirea documentelor de constatare. La această obligativitate de a vă prezenta la unitatea de poliție competentă pe raza căreia s-a produs accidentul în termen de cel mult 24 de ore de la producerea evenimentului sunt prevăzute următoarele excepții:","imageUrl":"/nivel-1/quiz-images/rodrive-all/0579.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0579.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 579; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 578 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/ce-masuri-ia-conducatorul-de-vehicul-angajat-intr-un-accident-cu-avarii-usoare","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"578","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0580","batch":"12","category":"Categoria B","question":"Cum veți proceda corect la întâlnirea indicatoarelor „Oprire“ și „Trecere la nivel cu o cale ferată dublă fără bariere“?","answers":["Opriți și vă asigurați, la 1 m de calea ferată","Reduceți viteza și traversați cu atenție linia ferată","Opriți în locul în care există vizibilitate maximă asupra căii ferate, fără a depăși indicatoarele menționate sau marcajul pentru oprire"],"correctIndices":[2],"correct":2,"explanation":"Atunci când vă apropiați de o trecere la nivel cu o cale ferată curentă și întâlniți indicatorul „Trecere la nivel cu o cale ferată dublă, fără bariere”, însoțit de indicatorul „Oprire”, aveți obligația de a opri în locul în care există vizibilitate maximă asupra căii ferate fără a trece de aceste indicatoare sau, după caz, înaintea marcajului pentru oprire și să vă asigurați că din partea stângă sau din partea dreaptă nu se apropie niciun vehicul feroviar, după care vă puteți continua deplasarea.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0580.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0580.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 580; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 579 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/cum-veti-proceda-corect-la-intalnirea-indicatoarelor-oprire-si-trecere-la-nivel-cu-o-cale-ferata-dubla-fara-bariere","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"579","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0581","batch":"12","category":"Categoria B","question":"Circulați cu un autovehicul / tractor agricol sau forestier, cu remorcă, pe o șosea cu o singură bandă pentru fiecare direcție și vă apropiați de o curbă la stânga, foarte strânsă și fără vizibilitate. Cum trebuie să adaptați modul de conducere?","answers":["Reduceți viteza înaintea curbei, din cauza pericolului mărit de derapare a remorcii","Reduceți viteza, circulați pe mijlocul benzii și accelerați ușor când ajungeți în vârful curbei","Mențineți viteza, iar în curbă frânați"],"correctIndices":[0],"correct":0,"explanation":"Aveți obligația să circulați cu o viteză care să nu depășească 30 km/h, în localități, sau 50 km/h în afara localităților, în curbele deosebit de periculoase semnalizate ca atare sau în care vizibilitatea este mai mică de 50 de metri. Iar dacă autoturismul pe care îi conduceți are atașată o remorcă veți reduce din timp viteza (înainte de curbă), deoarece pericolul de derapaj al remorcii este foarte mare. Parcurgerea unei curbe se face cu viteză redusă și constantă, iar abia după ieșirea din curbă, când vizibilitatea este bună, puteți accelera. Când ajungeți în vârful curbei, adică în mijlocul acesteia,NUeste momentul potrivit pentru a accelera. Momentul potrivit pentru a accelera este chiar după ieșirea din curbă, atunci când aveți și cea mai bună vizibilitate. Nu se recomandă să frânați în interiorul curbei, frânarea se face înainte de curbă. Dacă frânați în interiorul curbei, remorca va avea tendința să se deplaseze pe direcția înainte și apare fenomenul de supravirare a remorcii.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0581.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0581.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 581; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 580 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/circulati-cu-un-autovehicul-tractor-agricol-sau-forestier-cu-remorca-pe-o-sosea-cu-o-singura-banda-pentru-fiecare-directie-si-va-apropiati-d","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"580","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0582","batch":"12","category":"Categoria B","question":"Ce obligație îi revine conducătorului de vehicul care schimbă direcția de mers la dreapta, la semnalul verde al semaforului, în timp ce pietonii sunt angajați la rândul lor în traversare?","answers":["Să semnalizeze schimbarea direcției de mers și să acorde prioritate de trecere pietonilor angajați în traversarea străzii pe care urmează să intre, pe sensul său de mers","Să semnalizeze schimbarea direcției de mers și să-și continue deplasarea cu prudență, pietonii fiind obligați să-i cedeze trecerea","Să semnalizeze schimbarea direcției de mers și să păstreze o distanță laterală suficientă față de bordura din dreapta"],"correctIndices":[0],"correct":0,"explanation":"Conducătorul de vehicul care schimbă direcția de mers spre dreapta, chiar dacă semaforul este pe culoarea verde, are obligația de a acorda prioritate de trecere pietonilor angajați regulamentar în traversarea străzii pe care dorește să intre, când aceștia se află pe sensul de mers al vehiculului.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0582.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0582.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 582; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 581 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/ce-obligatie-ii-revine-conducatorului-de-vehicul-care-schimba-directia-de-mers-la-dreapta-la-semnalul-verde-al-semaforului-in-timp-ce-pieton","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"581","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0583","batch":"12","category":"Categoria B","question":"Ce interdicție aveți în această situație?","answers":["Să acordați prioritate vehiculelor care intră în intersecție","Să opriți vehiculul","Să circulați cu o viteză mai mică de 30 km pe oră"],"correctIndices":[1],"correct":1,"explanation":"În situația dată, întenționând să pătrundeți în intersecție vă este interzisă oprirea voluntară, deoarece oprirea voluntară a vehiculelor este interzisă în intersecții, inclusiv în cele cu circulație în sens giratoriu.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0583.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0583.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 583; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă o intersecție giratorie semnalizată corespunzător. În dreptul șoferului se observă un indicator triunghiular cu margini roșii, de cedare a trecerii. Atenție! Se întreabă „ce interdicție aveți?”. Trebuie să țineți cont că în toate situațiile din chestionare în care se face referire la OPRIRE, este vorba despre OPRIREA VOLUNTARĂ","needsImageReview":true,"source":"RoDrive · ID 582 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/ce-interdictie-aveti-in-aceasta-situatie","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"582","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_597.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0584","batch":"12","category":"Categoria B","question":"La întâlnirea cărui indicator aveți prioritate de trecere?","answers":["„circulație în ambele sensuri\"","„prioritate față de circulația din sens invers\"","„prioritate pentru circulația din sens invers\""],"correctIndices":[1],"correct":1,"explanation":"Indicatorul „Circulație în ambele sensuri” se întâlnește la ieșire de pe un drum cu sens unic și are rolul de a atenționa conducătorul de autovehicul că pe sectorul de drum următor se va circula în ambele sensuri. La întâlnirea indicatorului „Prioritatefațăde circulația din sens invers” conducătorul de vehicul are prioritate față de toate vehiculele care circulă din sens opus. Acest indicator rutier se întâlnește pe sectoarele de drum îngustat, unde nu au loc să circule două vehicule, unul pe lângă celălalt. La întâlnirea indicatorului „Prioritatepentrucirculația din sens invers”, conducătorul de vehicul pierde prioritatea față de toate vehiculele care circulă din sens opus. Acest indicator rutier se întâlnește pe sectoarele de drum îngustat, unde nu au loc să circule două vehicule, unul pe lângă celălalt. Prin urmare, veți avea prioritate de trecere la întâlnirea indicatorului „Prioritatefațăde circulația din sens invers”.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0584.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0584.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 584; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 583 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/la-intalnirea-carui-indicator-aveti-prioritate-de-trecere","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"583","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0585","batch":"12","category":"Categoria B","question":"La întâlnirea acestui indicator, aveți obligația:","answers":["Să sporiți atenția, deoarece la o distanță de 50 m urmează o intersecție cu un drum prioritar","Nu aveți nicio obligație, întrucât circulați pe un drum prioritar","Să acordați prioritate de dreapta la indicatorul următor"],"correctIndices":[0],"correct":0,"explanation":"În situația dată întâlniți indicatorul „Cedează trecerea” însoțit de panoul adițional „Stop 50 metri”, acest indicator împreună cu panoul adițional are rolul de a vă informa că peste 50 de metri urmează o intersecție în care veți întâlni indicatorul „Oprire”. Prin urmare, în situația dată trebuie să sporiți atenția deoarece peste 50 de metri urmează o intersecție cu un drum care are prioritate, unde trebuie să opriți și să acordați prioritate de trecere. Indicatorul împreună cu panoul adițional vă informează că vă aflațipe un drum fără prioritate, nu pe un drum prioritar, așa cum se specifică în această variantă de răspuns. Prin urmare, varianta B de răspuns nu poate fi corectă. La întâlnirea următorului indicator, mai exact a indicatorului „Oprire”, care se întâlnește în următoarea intersecție, trebuie să opriți și să acordați prioritate de trecere vehiculelor care circulă pe drumul prioritar, indiferent din ce parte circulă acestea. Prioritatea de dreapta se va acorda în intersecțiile cu circulație nedirijată. Prin urmare, varianta C de răspuns nu poate fi corectă.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0585.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0585.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 585; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă un indicator triunghiular cu margini roșii, care semnalează 'cedează trecerea' urmat de un indicator 'STOP' amplasat la 50 de metri înainte de intersecție. Sub indicatorul de cedare a trecerii, se află un panou adițional pe care scrie 'STOP 50 m', ce semnifică faptul că in 50 de metri urmează intersecția unde trebuie cedată trecerea","needsImageReview":true,"source":"RoDrive · ID 584 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/la-intalnirea-acestui-indicator-aveti-obligatia","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"584","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_599.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0586","batch":"12","category":"Categoria B","question":"În ce ordine vor circula autoturismele prin intersecțiile prezentate?","answers":["Albastru, roșu, galben","Roșu, albastru, galben","Galben, roșu, albastru"],"correctIndices":[1],"correct":1,"explanation":"Intersecțiile din imagine sunt dirijate cu semnale luminoase și cu indicatoare de reglementare de prioritate. Autoturismul roșu are prioritate de trecere deoarece întâlnește semnalul verde al semaforului. Autoturismul albastru întâlnește indicatorul „Cedează trecerea” și trebuie să îi acorde autoturismului roșu prioritate de trecere. Autoturismul galben întâlnește semnalul roșu al semaforului și nu își poate continua deplasarea, trebuie să aștepte apariția semnalului de culoare verde al semaforului. Prin urmare, ordinea de trecere este următoarea: autoturismul roșu, urmat de autoturismul albastru, iar ultimul va trece autoturismul galben.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0586.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0586.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 586; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă o intersecție dirijată prin semafor și indicator 'Cedează trecerea'. Vehiculul roșu(de jos) are semafor verde și intenționează să se deplaseze înainte. Vehiculul galben(din stânga) așteaptă la semafor roșu, iar vehiculul albastru(din dreapta) intenționează să vireze la dreapta. Vehiculul albastru are în față un indicator triunghiular cu margini roșii, ce îl obligă să cedeze trecerea mașinilor din intersecție.","needsImageReview":true,"source":"RoDrive · ID 585 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/in-ce-ordine-vor-circula-autoturismele-prin-intersectiile-prezentate","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"585","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_600.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0587","batch":"12","category":"Categoria B","question":"Este interzisă staționarea unui vehicul pe un drum public cu o lățime mai mică de 6 m?","answers":["Da","Nu","Legal, nu este prevăzut"],"correctIndices":[0],"correct":0,"explanation":"Se interzice, prin regulamentul rutier,staționareavoluntară a vehiculelor pe drumurile publice cu o lățime mai mică de 6 metri. Atenție! Pe aceste drumuri nu este interzisă și manevra deoprire. Trebuie știut că diferența dintre oprire și staționare constă în perioada de timp pe care este imobilizat vehiculul. O imobilizare a vehiculului de până la 5 minute se numește oprire, iar dacă durează mai mult de 5 minute, se numește staționare. Prin urmare, daca imobilizarea vehiculului este de pana la 5 minute, se numește oprire și este permisă în locurile în care este interzisă staționarea.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0587.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0587.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 587; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 586 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/este-interzisa-stationarea-unui-vehicul-pe-un-drum-public-cu-o-latime-mai-mica-de-6-m","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"586","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0588","batch":"12","category":"Categoria B","question":"La semnalul polițistului situat într-o intersecție, cu brațul ridicat vertical, aveți obligația:","answers":["Să circulați cu prudență maximă","Să reduceți viteza","Să opriți, indiferent din ce direcție circulați"],"correctIndices":[2],"correct":2,"explanation":"Brațul polițistului rutier ridicat vertical semnifică oprire pentru toți participanții la trafic care se apropie, indiferent din ce direcție circulă aceștia. Acest semnal este un semnal premergător, după efectuarea lui așteptați următorul semnal al polițistului, ca de exemplu ridicarea brațelor în plan orizontal.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0588.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0588.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 588; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 587 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/la-semnalul-politistului-situat-intr-o-intersectie-cu-bratul-ridicat-vertical-aveti-obligatia","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"587","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0589","batch":"12","category":"Categoria B","question":"Pe autostradă se interzice:","answers":["Circulația autovehiculelor în coloană","Învățarea conducerii unui vehicul, încercarea prototipurilor de șasiuri și de vehicule cu motor","Executarea de lucrări pe partea carosabilă pe timp de noapte"],"correctIndices":[1],"correct":1,"explanation":"Pe autostradă se interzice învățarea conducerii vehiculelor, ca de exemplu efectuarea ședințelor de conducere oferite de școlile de șoferi sau de alte centre de pregătire sau instruire, precum și încercările prototipurilor de șasiuri și de autovehicule, cum ar fi autovehicule aflate în etapa de testare și dezvoltare a unor noi concepte și tehnologii. Circulația autovehiculelor în coloană pe autostradă și executarea de lucrări pe partea carosabilă a autostrăzii pe timp de noapte nu sunt prevăzute a fi interzise în legislația rutieră, astfel acestea sunt permise, cu condiția să se respecte toate reglementările legislative în vigoare.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0589.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0589.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 589; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 588 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/pe-autostrada-se-interzice","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"588","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0590","batch":"12","category":"Categoria B","question":"Indicatorul vă interzice depășirea?","answers":["Da","Nu","Indicatorul nu vi se adresează"],"correctIndices":[0],"correct":0,"explanation":"În situația dată întâlniți indicatorul „Depășirea autovehiculelor, cu excepția motocicletelor fără ataș, interzisă”. Acest indicator vă interzice depășirea tuturor autovehiculelor, cu excepția motocicletelor fără ataș și a mopedelor. Prin urmare, în situația dată nu puteți depăși niciunui autovehicul, dar puteți depăși motociclete fără ataș și mopede, pentru că acestea sunt considerate excepții de la această interzicere. De asemenea, aveți voie să depășiți și vehicule simple (biciclete, vehicule cu tracțiune animală, vehicule trase sau împinse cu mâna). Pentru a asigura odistanță laterală de siguranță corespunzătoare, conducătorii de autovehicule (cu excepția autovehiculelor cu două roți), vor efectua manevra de depășire a bicicletelor sau a trotinetelor electrice respectând,pe lângă obligațiile privind manevra de depășire,și următoarele obligații,în funcție de viteza cu care aceștia se deplasează(art. 118 alin. 2 din Regulament): În concluzie, dacă te deplasezicu până la 50de km/h ești obligatmăcar să încalci marcajul, iar dacă te deplasezicu mai mult de 50 de km/hești obligatmăcar să treci cu jumătate din lățimea autovehiculului peste marcaj. Trebuie reținut că acestea de mai sus nu sunt doar recomandări, acestea sunt obligații, iar nerespectarea lor se sancționează conform legii. De reținut că în cazul în care un sector de drum are acest marcaj realizat culinie continuănu se mai poate efectua depășirea bicicletelor sau trotinetelor electrice, pentru căeste interzisă încălcarea sau trecerea peste acest marcaj cu linie continuă, iarpentru depășirea acestor vehicule este ob","imageUrl":"/nivel-1/quiz-images/rodrive-all/0590.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0590.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 590; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă un indicatorul circular cu margini roșii, indicatorul având în interior o mașină roșie în stânga și una neagră în dreapta, ce semnifică depășirea interzisă, este amplasat pe un drum curbat.","needsImageReview":true,"source":"RoDrive · ID 589 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/indicatorul-va-interzice-depasirea","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"589","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_604.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0591","batch":"12","category":"Categoria B","question":"Puteți schimba poziția vehiculului, dacă sunteți implicat într-un accident de circulație?","answers":["Da, după ce ați acordat primul ajutor victimelor","Da, după ce ați anunțat poliția","Da, dacă accidentul s-a soldat numai cu avarii"],"correctIndices":[2],"correct":2,"explanation":"În cazul în care ați fost implicat într-un accident de circulație în urmă căruia a rezultat moartea sau vătămarea integrității corporale ori a sănătății unei persoane sunteți obligat să anunțați imediat poliția și să apelați numărul național unic pentru apeluri de urgență 112, să nu modificați sau să ștergeți urmele accidentului și să nu părăsiți locul faptei. Prin urmare, în cazul variantei A de răspuns,chiar dacă acordați sau nu victimelor primul ajutor,nu se va putea schimba poziția vehiculului. După anunțarea poliției,NUse poate schimba poziția vehiculului în toate situațiile. Dacă în urma accidentuluia rezultat moartea sau vătămarea integrității corporale ori a sănătății unei persoaneNUse poate schimba poziția vehiculului, chiar dacă ați anunțat poliția, în această situație sunteți obligat să anunțați imediat poliția și să apelați numărul național unic pentru apeluri de urgență 112,să nu modificați sau să ștergeți urmele accidentului și să nu părăsiți locul faptei. În schimb, dacă accidentul s-a soldatnumai cu avarierea vehiculelor și/sau alte pagube materiale(fără victime), se poate schimba poziția vehiculului, iar anunțarea poliției se va face la unitatea de poliție competentă pe raza căreia s-a produs accidentul în termen de cel mult 24 de ore de la producerea evenimentului. Conducătorul de vehicul implicat într-un accident de circulațieîn urma căruia au rezultat numai avarierea vehiculelor și/sau alte pagube materiale(fără victime), este obligat să scoată imediat vehiculul în afara parții carosabile ori, dacă starea vehiculului nu permite acest lucru, să îl deplase","imageUrl":"/nivel-1/quiz-images/rodrive-all/0591.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0591.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 591; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 590 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/puteti-schimba-pozitia-vehiculului-daca-sunteti-implicat-intr-un-accident-de-circulatie","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"590","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0592","batch":"12","category":"Categoria B","question":"Intenționați să consultați o hartă rutieră. Cum este recomandat să procedați?","answers":["Opriți, cu luminile de întâlnire aprinse","Opriți autovehiculul în afara carosabilului","Nu aveți voie să consultați harta pe timp de noapte"],"correctIndices":[1],"correct":1,"explanation":"Conducătorilor de vehicule le este interzis să aibă în timpul mersului preocupări de natură a le distrage în mod periculos atenția. Consultarea unei harți în timpul deplasării reprezintă un astfel de comportament. Deci trebuie să opriți autovehiculul în afara parții carosabile, imediat ce acest lucru este posibil și se poate face în condiții de siguranță, astfel veți putea consulta harta fără a pune în pericol siguranța circulației rutiere. Marcajul o linie continuă aplicat la marginea din dreapta părții carosabile interzice staționarea, manevra de oprire fiind permisă.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0592.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0592.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 592; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă un drum cu linie continuă dublă și trafic intens, inclusiv vehicule mari. Șoferul este la volan și ar dori să consulte o hartă rutieră.","needsImageReview":true,"source":"RoDrive · ID 591 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/intentionati-sa-consultati-o-harta-rutiera-cum-este-recomandat-sa-procedati","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"591","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_606.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0593","batch":"12","category":"Categoria B","question":"Ce trebuie să aveți în vedere dacă intenționați să circulați spre dreapta, după taxi?","answers":["Pietonii vor acorda prioritate necondiționat","Să acordați prioritate pietonilor aflați pe sensul dumneavoastră de mers","Pietonii nu au voie să traverseze în acest loc"],"correctIndices":[1],"correct":1,"explanation":"În situația dată, virând către dreapta, chiar dacă întâlniți indicatorul „Drum cu prioritate”, aveți obligația de a acorda prioritate de trecere pietonilor angajați în traversarea regulamentară a drumului pe care doriți să intrați, atunci când aceștia se află pe sensul dumneavoastră de mers.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0593.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0593.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 593; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă un taxi într-o intersecție, din perspectiva șoferului din spatele său. Taxi-ul intenționează să circule spre dreapta, prin dreptul unei treceri de pietoni. Pietonii sunt angajați în traversare.","needsImageReview":true,"source":"RoDrive · ID 592 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/ce-trebuie-sa-aveti-in-vedere-daca-intentionati-sa-circulati-spre-dreapta-dupa-taxi","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"592","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_607.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0594","batch":"12","category":"Categoria B","question":"Cum se recomandă să procedați pentru a conduce ecologic un autovehicul?","answers":["Să utilizați frâna de motor pentru a încetini","Să scoateți autovehiculul din viteză în timpul frânării","Să folosiți frâna de mână concomitent cu frâna de serviciu, pentru a obține o frânare rapidă și eficientă"],"correctIndices":[0],"correct":0,"explanation":"Pentru a conduce ecologic se recomandă evitarea, pe cât posibil, a accelerărilor și a frânărilor bruște. Utilizarea frânei de motor pentru a încetini autovehiculul este o caracteristică a conducerii ecologice și se recomandă în vederea economisirii combustibilului și prelungirii duratei de viață a elementelor frânei de serviciu (frâna de picior). Scoaterea autovehiculului din viteză la frânare nu este un element al conducerii ecologice și nu se recomandă la frânările pentru încetinire, se scoate autovehiculul din viteză doar atunci când frânați considerabil intenționând să opriți. Decuplarea transmisiei în timpul mersului se interzice prin regulamentul rutier. Utilizarea frânei de mână concomitent cu cea de serviciu nu este un element al conducerii ecologice si nu se recomandă în nicio situație. Frâna de mână (frână de staționare) se folosește doar la staționare.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0594.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0594.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 594; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 593 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/cum-se-recomanda-sa-procedati-pentru-a-conduce-ecologic-un-autovehicul","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"593","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0595","batch":"12","category":"Categoria B","question":"Cui trebuie să acordați prioritate dacă vă aflați în autoturismul albastru?","answers":["Autobuzului, fiind vehicul de transport public de persoane","Autoturismului roșu, deoarece nu-și schimbă direcția de mers","Ambelor vehicule"],"correctIndices":[2],"correct":2,"explanation":"Intersecția din imagine este nedirijată, situație în care se va aplica regula priorității de dreapta. Dumneavoastră, conducând autoturismul albastru, aveți obligația de a acorda autobuzului și autoturismului roșu prioritate, deoarece aceștia vă vin din partea dreaptă. În situația dată trebuie să acordați prioritate de trecere ambelor autovehicule.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0595.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0595.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 595; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă o intersecție nesemaforizată văzută de sus. Vehiculul albastru aflat în stânga intenționează să vireze la stânga. Autoturismul și autobuzul se află în partea de jos și intenționează să se deplaseze înainte, respectiv să vireze la stânga.","needsImageReview":true,"source":"RoDrive · ID 594 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/cui-trebuie-sa-acordati-prioritate-daca-va-aflati-in-autoturismul-albastru","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"594","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_609.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0596","batch":"12","category":"Categoria B","question":"Un vehicul va fi imobilizat dacă:","answers":["Numărul de înmatriculare sau de înregistrare este fals","Starea tehnică a pneurilor este necorespunzătoare","Conducătorul auto refuză să poarte centura de siguranță"],"correctIndices":[0],"correct":0,"explanation":"Imobilizarea unui autovehicul, tramvai, tractor agricol ori forestier se dispune de către polițistul rutier pentru conducerea acestuia având număr fals de înmatriculare sau înregistrare. Pe lângă imobilizarea vehiculului, această faptă se pedepsește penal, cu închisoare de la unu la 5 ani sau cu amendă, se va aplica măsura de reținere a permisului de conducere în vederea anulării acestuia, eliberându-se o dovadă înlocuitoare a acestuia fără drept de circulație. Dacă starea tehnică a pneurilor este necorespunzătoare se va sancționat cu amenda contravențională prevăzută în clasa a II-a de sancțiuni și cu reține certificatului de înmatriculare sau de înregistrare, eliberându-se o dovadă înlocuitoare a acestuia cu drept de circulație pentru 15 zile. Pentru această contravenție NU se dispune imobilizarea vehiculului. În cazul în care conducătorul auto refuză să poarte centura de siguranță și este depistat de polițistul rutier, acesta va fi sancționat cu amenda prevăzută în clasa I de sancțiuni și cu aplicarea a 2 puncte de penalizare. Pentru această contravenție NU se dispune imobilizarea vehiculului.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0596.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0596.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 596; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 595 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/un-vehicul-va-fi-imobilizat-daca","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"595","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0597","batch":"12","category":"Categoria B","question":"Care dintre cele trei autovehicule a parcat regulamentar?","answers":["Niciunul","Autoturismul 3","Autoturismele 1 și 2"],"correctIndices":[0],"correct":0,"explanation":"Indicatorul împreună cu panoul adițional instalat sub acesta confirmă o zonă special amenajată pentru parcare, unde vehiculele vor parca paralel cu drumul și cu două roți pe trotuar. Prin urmare, niciunul dintre autovehicule nu a parcat regulamentar, deoarece nu au parcat cu două roți pe trotuar. La întâlnirea acestui indicator parcarea se efectuează paralel cu drumul și cu două roți pe trotuar.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0597.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0597.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 597; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă un indicator dreptunghiular albastru pe care scrie P cu alb. Tot în interiorul indicatorului se află o mașină cu două roți pe trotuar și două roți pe stradă. Acest indicator, împreună cu panoul adițional cu săgeată bidirecțională semnifică zonă de parcare unde vehiculele trebuie să parcheze paralel cu șoseaua, cu două roți pe stradă și două roți pe trotuar. Autoturismul 1 este parcat lateral cu drumul, după indicator, cu toate roțile pe trotuar. Autoturismul 2 este parcat lateral cu drumul, în fața indicatorului, cu toate roțile pe trotuar. Autoturismul 3 este parcat pe stradă, paralel cu drumul.","needsImageReview":true,"source":"RoDrive · ID 596 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/care-dintre-cele-trei-autovehicule-a-parcat-regulamentar","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"596","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_611.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0598","batch":"12","category":"Categoria B","question":"Ce veți respecta în intersecția prezentată?","answers":["Semnificația luminii semaforului","Regula priorității de dreapta","Semnificația indicatoarelor"],"correctIndices":[0],"correct":0,"explanation":"Conducătorul de vehicul este obligat să respecte semnificația semnalizării luminoase cu prioritate față de semnificația indicatoarelor de reglementare de prioritate. Prin urmare, în această situație trebuie să respectați semnificația luminii roșii a semaforului și trebuie să opriți. Semnificația indicatoarelor de reglementare de prioritate instalate lângă semafoare se va respecta când semafoarele nu funcționează sau funcționează pe culoarea galbenă intermitentă.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0598.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0598.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 598; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă o trecere de pietoni semaforizată cu indicator octogonal 'STOP'. Semaforul este activ și este roșu","needsImageReview":true,"source":"RoDrive · ID 597 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/ce-veti-respecta-in-intersectia-prezentata","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"597","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_612.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0599","batch":"12","category":"Categoria B","question":"Cum veți proceda în situația dată?","answers":["Veți vira ultimul","Camionul va trece primul","Aveți prioritate"],"correctIndices":[2],"correct":2,"explanation":"În situația dată întâlniți indicatorul “Drum cu prioritate”, însoțit de unpanou adiționalcare vă indică direcția drumului cu prioritate. Intenționând să schimbați direcția de mers către stânga, veți circula pe drumul cu prioritate și veți avea prioritate de trecere. Autocamionul părăsind drumul cu prioritate, trebuie să vă acorde prioritate de dreapta, iar autoturismul întâlnește indicatorul “Cedează trecerea” și trebuie să vă acorde prioritate de trecere. Prin urmare, în situația dată vă puteți continua deplasarea deoarece aveți prioritate de trecere.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0599.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0599.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 599; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă o intersecție dn perspectiva unui șofer, având în față un indicator în formă de romb, cu margine albă și fundal galben, însoțit de un panou adițional care îngroașă drumul pe care se află șoferul și continuă la stânga. Acestea indică faptul că drumul prioritar este cel îngroșat. Șoferul intenționează să vireze pe direcția drumului îngroșat. De pe sensul opus o mașina vrea să meargă înainte, iar din stânga, un camion dorește să meargă înainte.","needsImageReview":true,"source":"RoDrive · ID 598 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/cum-veti-proceda-in-situatia-data","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"598","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_613.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0600","batch":"12","category":"Categoria B","question":"Cum se procedează cu accidentatul readus la viață prin resuscitare cardio-respiratorie?","answers":["Se va transporta la domiciliu sau la locul de muncă","Se va transporta întotdeauna la o unitate medicală specializată","Se va aștepta sosirea poliției rutiere"],"correctIndices":[1],"correct":1,"explanation":"Accidentatul readus la viață cu ajutorul resuscitării cardio-respiratorie se va transporta întotdeauna la o unitate medicală specializată pentru investigații de specialitate în vederea asigurării că toate funcțiile organismului sunt în stare bună.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0600.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0600.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 600; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 599 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/cum-se-procedeaza-cu-accidentatul-readus-la-viata-prin-resuscitare-cardio-respiratorie","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"599","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"}]);})();
